    }

    return hash;
}

int main(void)
{
    // строки для примера
    char* red = "red";
    char* green = "green";

    // получаем хеш строки
    unsigned int red_hash = hash_fnv1a(red);
    unsigned int green_hash = hash_fnv1a(green);

    unsigned int size = 4;      // размер хеш-таблицы - для примера только 4 корзины
    struct hash_table* dict = new_table(size);

    // добавляем строки в хеш-таблицу
    insert_key(dict, red_hash);
    insert_key(dict, green_hash);

    // проверим, есть ли строка red в таблице
    int is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем строку из хеш-таблицы
    delete_key(dict, red_hash);

    delete_key(dict, red_hash-2);
    // снова проверяем, есть ли строка в хеш-таблице
    is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем всю хеш-таблицу
    free_table(dict);

    return 0;
}
```



Здесь для примера добавляем пару строк и затем проверям наличие одной из них в хеш-таблицы - до и после удаления.

Смысл открытой адресации (open addressing) в том, чтобы хранить все элементы непосредственно в массиве самой хеш-таблицы, как и при прямой адресации, не создавая дополнительных структур вроде связных списков. Как и в общем случае, вычисляется индекс для вставки данных (например, путем получения остатка от деления хеша на размер таблицы). Однако если есть коллизии и нужный индекс уже используется, то для хранения значения надо найти другую свободную ячейку. Такой поиск еще называют "зондированием" (probing).



Подобный подход позволяет сэкономить память, так как не нужно тратить ресурсы на указатели и узлы списков. Кроме того, обеспечивается сравнительно высокая скорость (Cache locality): поскольку все данные лежат в памяти рядом (в одном массиве), процессор обрабатывает их быстрее, чем "прыгая" по ссылкам в разные части памяти.



Основной минус: в отличие от стратегии со связанными списками при открытой адресации в таблице может кончиться место для новых ключей. Поэтому необходимо иметь стратегию на случай заполнения таблицы на 100%. Обычно при заполнении на 70-80% ее приходится расширять. Кроме того, чем больше таблица забита, тем дольше длится поиск свободной ячейки.





### Стратегии зондирования




Ключевая проблема при открытой адресации заключается в поиске незанятых ячеек, куда можно вставить новые данные, или то, что называется стратегией зондирования. Распространены следующие три стратегии:





- Линейное зондирование (linear probing): если место i занято, проверяем i+1, затем i+2 и так далее, пока не найдем пустое место.

- Квадратичное зондирование : расстояние между проверками увеличивается квадратично (1, 4, 9...), что помогает избежать скопления элементов в одном месте.

- Двойное хеширование (double hashing): интервал поиска определяет вторая хеш-функция.




Стратегию зондирования можно выразить функцией `p(k, i)`, которая возвращает индекс и которая зависит от хеш-ключа k и индекса i (который изменяется от 0 до m - 1, где m обозначает размер хеш-таблицы). При вставке в таблицу хеш-значения k сначала мы пытаемся добавить его по индексу `p(k, 0)`. Если этот слот занят, то вместо этого мы пытаемся использовать `p(k, 1)`. Если же и этот слот тоже занят, то переходим к `p(k, 2)` и так далее. В итоге мы проверяем последовательность `p(k, 0), p(k, 1), p(k, 2), ..., p(k, m-1)`. Таким образом, если вся таблица еще не заполнена, то мы так или иначе найдем пустое место для размещения данных.




Рассмотрим в обшем виде пару стратегий.



#### Линейное зондирование (linear probing)



**Линейное зондирование** (linear probing) представляет самую простую в реализации стратегию. Она подразумевает линейный поиск от индекса, чтобы добраться от ключа до конца таблицы, а затем переход к началу таблицы. Такая стратегия выражается формулой:



```c
p(key, index) = (key + index) mod size
```



Общий процесс вставки ключа выглядит следующим образом:





- Вычисляется индекс: p = (key + 0) % size.

- Если ячейка p занята, проверяем p + 1 или ( (key + 1) % size ) .

- Если и она занята - проверяем p + 2, и так далее по кругу, пока не найдется пустая ячейка.

- При поиске алгоритм точно так же идет по цепочке, пока не найдет нужный ключ или пустую ячейку (что означает, что ключа нет).




Главный минус подобной стратегии - так называемая **первичная кластеризация** (Primary Clustering). Она заключается в том, что занятые ячейки имеют свойство группироваться в длинные блоки. Чем длиннее такой "кластер", тем больше проверок приходится делать, что замедляет работу таблицы до линейного времени O(n).



При этом надо учитывать, что последовательности для разных ключей могут накладываться друг на друга. Например, возьмем, что для ключа k1 индекс будет равен P1, но, допустим он занят. Тогда при наличии сводобных ячеек мы можем найти некий индекс Pn и в его ячейку поместить ключ. Но пусть у нас также будет второй ключ k2, базовый индекс которого равен P2 и находится между P1 и Pn - `[P1...P2...Pn]`. Поскольку все ячейки вплоть для Pn заняты, то для ключа k2 выбираем индекс P(n+1).



Таким образом, ключ страдает от коллизий ключа, хотя их изначальные индексы были разными. Чем длиннее такой общий кластер, тем больше шагов (проб) нужно сделать как для вставки, так и для поиска




Но перейдем к коду. Предположим, что размер таблиц представляет степень двойки, а это значит, что можено заменить операцию получения остатка на маскирование и реализовать зондирование следующим образом:



```c

unsigned int p(unsigned int key, unsigned int index, unsigned int size)
{
    return (key + index) & (size - 1);
}
```






#### Двойное хеширование



**Двойное хеширование** (double hashing) предполагает использование двух разных хеш-функций: одна сопоставляет ключ с начальным индексом, а другая определяет последовательность зондирования. Двойное хеширование выражается через следующую формулу:



```c
p(key, ind) = (hash_func_1(key) + ind * hash_func_2(key)) mod size
```



Где `key` - ключ, `hash_func_1` и `hash_func_2` - функции хеширования, `ind` - начальный индекс, `size` - количество ячеек таблицы.



Смысл двойного хеширования состоит в том, чтобы при поиске свободной ячейки сделать шаг ("прыжок"), который будет индивидуальным для каждого ключа. В формуле выше подвыражение `hash_func_2(key)` по сути и представляет шаг. В линейном пробировании шаг всегда равен 1 (или константе). Из-за этого все ключи, попавшие в одну область, выстраиваются в одну длинную очередь (кластер). Двойное хеширование разбивает эти очереди.



Таким образом, даже если у двух разных ключей k_1 и k_2 совпал основной индекс (`hash_func_1(key)`), их вторые хеш-функции (`hash_func_2(key)`) почти наверняка выдадут разные значения шага. В итоге они не "слипаются" в один кластер, а разлетаются по разным частям таблицы. Это полностью решает проблему первичной кластеризации.




На данный момент можно предположить, что ключи уже являются хеш-ключами и, следовательно, `hash_func_1` будет тождественной функцией (identity function), то есть `key = hash_func_1(key)`. Поэтому основная задача состоит в подборе второй функции - `hash_func_2`. Чтобы она работала эффективно, она должна отвечать двум главным критериям:





- Никогда не должна возвращать 0 (иначе шаг будет нулевым, и мы зациклимся на одной ячейке)

- Результат hash_func_2(key) должен быть взаимно прост с размером таблицы size (То есть наибольший общий делитель hash_func_2(key) и размера таблицы равен 1). Это гарантирует, что в процессе прыжков мы со временем посетим все ячейки таблицы, а не будем ходить по кругу в узком цикле.



Кроме того, эта функция не должна быть просто модификацией первой функцией хеширования или зависеть от нее (например, `hash_func_1(key) \ 2`), иначе распределение останется похожим, и мы снова получим кластеризацию. И также в идеале она должна вычисляться быстро, так как при высокой нагрузке на таблицу ее придется считать часто.



Самые популярные способы определения функции:





- Если размер таблицы - простое число В этом случае вторую функцию можно вычислять по формуле hash_func_2(key) = R - (key mod R) , где R - простое число, чуть меньшее, чем размер таблицы. Вычитание из R гарантирует, что результат будет в диапазоне [1, R] , то есть никогда не будет равен 0. Так как размер таблицы представляет простое число, то любое число hash_func_2(key)  


- Рехеширование кластера (Backshift Removal) : это более сложный, но в то же время более "чистый" способ без использования маркеров, который выглядит следующим образом: Удаляем нужный элемент.

- Проверяем следующую ячейку. Если она пуста - работа закончена.

- Если она занята, нужно проверить, не должен ли элемент в ней (назовем его X) переместиться назад на освободившееся место.

- Если "родной" индекс элемента X находится до или на месте только что освобожденной ячейки, сдвигаем X назад, а текущую позицию X помечаем как свободную.

- Повторяем процесс для следующей ячейки, пока не встретим пустоту.



Это позволяет сохранить структуру кластера плотной и исключает дыры и использование всяких маркеров.


 





### Реализация



Реализацию этой стратегии начнем с определения структуры корзины хеш-таблицы:



```c

struct bin 
{
    unsigned int key;
    int in_probe : 1;   // корзина - часть последовательности использованных корзин
    int is_empty : 1;   // корзина пуста (но может быть частью последовательности использованных корзин)
};
```



Здесь флаг `in_probe` может принимать одно из двух значений: 1 или 0 (по сути true или false). Зачем этот флаг нужен? С помощью этого флага реализуем "ленивое удаление" ("tombstones"), чтобы при простом последовательном переборе ячеек при поиске, когда алгоритм дойдет до этой ячейки, алгоритм не останавливался, если эта пустая ячейка пустая. Если флаг имеет значение 1 (true), то данный слот bin является частью последовательности зондирования, поэтому следует продолжить поиск, если искомый ключ еще не найден.




Флаг `is_empty` имеет значение 1 (true), если слот пуст, поэтому можно поместить в него значение. При вставке хеш-значения при последовательном поиске пустых ячеек можно проверять этот флаг, пока не будет найдена пустая ячейка с искомым индексом ключ или пока не дойдете до пустой ячейки, у которой `in_probe = 0`.




Далее определим структуру самой хеш-таблицы:



```c

struct hash_table 
{
    struct bin *bins;
    unsigned int size;
};
```



Здесь стандартное содержимое - поле-набор ячеек и размер таблицы.



При создании новой таблицы необходимо инициализировать каждую ячейку. Первоначально у ячеек bin не установлен флаг `in_probe`, но поскольку они пусты, установлен флаг `is_empty`:



```c

struct hash_table* new_table(unsigned int size)
{
    struct hash_table *table = malloc(sizeof *table);
    table->size = size;
    table->bins = malloc(size * sizeof *table->bins);

    // инициализация ячеек таблицы начальными значениями
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < size; i++) 
    {
        table->bins[i] = empty_bin;
    }
    return table;
}
```



Удаление таблицы стандартно: сначала освобождаем память под ячейки таблицы, а затем структуру самой таблицы:



```c

void free_table(struct hash_table *table)
{
    free(table->bins);
    free(table);
}
```




### Поиск пустых ячеек и ключей



Для вставки хеш-значений (с поиском свободных ячеек) или для поиска нужных хеш-ключей нам потребуется функция зондирования - `p(k, i)`, о которой шла речь в начале темы. Пока определим ее прототип:



```c
unsigned int p(unsigned int key, unsigned int i, unsigned int m);
```



Ее первый аргумент - вставляемое хеш-значение, второй аргумент - индекс для зондирования и последний аргумент - размер хеш-таблицы.



Затем используем эту функцию для написания двух вспомогательных функций. Первая функция будет находить первую пустую ячейку:



```c

struct bin* find_empty(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + p(key, i, table->size);
        // если ячейка пуста, возвращаем ее
        if (bin->is_empty) return bin;
    }
    // если пустых ячеек нет, пока для простоты возвращаем NULL
    return NULL;
}
```



Другая функция будет искать ячейку, которая заданный хеш-ключ (если он находится в таблице), и при этом эта ячейка не является пустой:



```c

struct bin* find_key(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin* bin = table->bins + p(key, i, table->size);

        // если хеш равен искомому, а яйчека не используется в зондировании
        // возвращаем данную ячейку
        if (bin->key == key && !bin->is_empty) return bin;
    }
    // иначе возвращаем NULL - индикатор, что ключ не найден
    return NULL;
}
```



### Проверка наличия ключа



Для проверки наличия хеш-ключа в таблице можно использовать функцию `find_key()`. Если она возвращает ячейку с искомым ключом, значит, данный ключ есть в таблице:



```c

int contains_key(struct hash_table* table, unsigned int key)
{
    struct bin *bin = find_key(table, key);
    return bin != 0;
}
```



При этом необходимо проверить и наличие ключа, и пустая ли ячейка, поскольку есть вероятность случайно найти ключ (например, ранее удаленный).



### Удаление



Для удаления ключа можно также использовать функцию `find_key()`:



```c

void delete_key(struct hash_table* table, unsigned int key)
{
    struct bin* bin = find_key(table, key);
    // если нашли ячейку с ключом, делаем ее пустой
    if(bin)
    {
        bin->is_empty = 1;
    }
}
```



Если `find_key()` возвращает ячейку с искомым ключом, то установливаем ее флаг `is_empty` в 1 (true).



### Вставка ключа



Для добавления хеш-ключа в таблицу необходимо выяснить, присутствует ли он уже в таблице - чтобы не вставлять его дважды. Если его нет, то вставить его в первое пустое место. Для первого шага можно использовать `contains_key()`, а для второго - `find_empty()`.



```c

void insert_key(struct hash_table* table, unsigned int key)
{
    if (!contains_key(table, key)) 
    {
        struct bin* bin = find_empty(table, key);
        // если пустые ячейки отсутствуют
        if(!bin)
        {
            printf("Unable to insert the key `%u`. No free bins\n", key);
            return;
        }
        // если нашли пустую ячейку, помещаем в нее данные
        *bin = (struct bin){.in_probe = 1, .is_empty = 0, .key = key};
    }
}
```



Если свободных ячеек больше нет, то в данном случае просто выводим диагностическое сообщение на консоль и выходим из функции.



### Полный пример



Соберем все вместе и посмотрим на примитивном примере:



```c

#include <stdio.h>
#include <stdlib.h>

// ячейка хеш-таблицы
struct bin 
{
    unsigned int key;
    int in_probe : 1;   // является ли частью последовательности зондирования
    int is_empty : 1;   // пустая ли ячейка
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;
};

// создание хеш-таблицы
struct hash_table* new_table(unsigned int size)
{
    struct hash_table *table = malloc(sizeof *table);
    table->size = size;
    table->bins = malloc(size * sizeof *table->bins);

    // инициализация ячеек таблицы начальными значениями
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < size; i++) 
    {
        table->bins[i] = empty_bin;
    }
    return table;
}

// удаление таблицы
void free_table(struct hash_table *table)
{
    free(table->bins);
    free(table);
}
// функция зондирования
// линейное зондирование
unsigned int p(unsigned int key, unsigned int i, unsigned int m)
{
    return (key + i) & (m - 1);
}
// двойное хеширование (double hashing)
unsigned int p2(unsigned int key, unsigned int i, unsigned int m)
{
    unsigned int h1 = key;
    unsigned int h2 = (key << 1) | 1;
    return (h1 + i*h2) & (m - 1);
}

// поиск ячейки с определенным ключом
struct bin* find_key(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin* bin = table->bins + p(key, i, table->size);

        // если хеш равен искомому, а яйчека не является пустой
        // возвращаем данную ячейку
        if (bin->key == key && !bin->is_empty) return bin;
    }
    // иначе возвращаем NULL - индикатор, что ключ не найден
    return NULL;
}
// поиск пустой ячейки
struct bin* find_empty(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + p(key, i, table->size);
        // если ячейка пуста, возвращаем ее
        if (bin->is_empty) return bin;
    }
    // если пустых ячеек нет, пока для простоты возвращаем NULL
    return NULL;
}

// проверка наличия ключа 
int contains_key(struct hash_table* table, unsigned int key)
{
    struct bin *bin = find_key(table, key);
    return bin != 0;
}

// удаление ключа
void delete_key(struct hash_table* table, unsigned int key)
{
    struct bin* bin = find_key(table, key);
    // если нашли ячейку с ключом, делаем ее пустой
    if(bin)
    {
        bin->is_empty = 1;
    }
}

// добавление ключа
void insert_key(struct hash_table* table, unsigned int key)
{
    if (!contains_key(table, key)) 
    {
        struct bin* bin = find_empty(table, key);
        // если пустые ячейки отсутствуют
        if(!bin)
        {
            printf("Unable to insert the key `%u`. No free bins\n", key);
            return;
        }
        // если нашли пустую ячейку, помещаем в нее данные
        *bin = (struct bin){.in_probe = 1, .is_empty = 0, .key = key};
    }
}

// получаем хеш-значение из строки
unsigned int hash_fnv1a(const char *str) 
{
   unsigned int hash = 2166136261u;

    while (*str) {
        hash ^= (unsigned char)(*str++);
        hash *= 16777619;
    }

    return hash;
}


// вывод хеш-таблицы
void print_table(struct hash_table* table)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + i;
        // просто выводим все ключи из непустых ячеек в строчку
        printf("%u", bin->is_empty?0:bin->key);
        if(i < table->size-1) printf(" - ");
    }
    putchar(10);
}

int main(void)
{
    unsigned int size = 4;
    struct hash_table* dict = new_table(size);
    
    // строки для примера
    char* colors[] = {"red", "green", "blue", "yellow", "black", "white"};
    for(int i =0; i < sizeof(colors)/sizeof(colors[0]); i++)
    {
        // получаем хеш строк
        unsigned int hash = hash_fnv1a(colors[i]);
        // добавляем строки в хеш-таблицу
        insert_key(dict, hash);
    }
    // выводим содержимое
    print_table(dict);

    // получаем хеш строки `red`
    unsigned int red_hash = hash_fnv1a(colors[0]); 

    // проверим, есть ли строка red в таблице
    int is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем строку `red` из хеш-таблицы
    printf("delete key %u\n", red_hash);
    delete_key(dict, red_hash);

    // снова проверяем, есть ли строка в хеш-таблице
    is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");


    // снова выводим содержимое для проверки
    print_table(dict);

    // удаляем всю хеш-таблицу
    free_table(dict);
    return 0;
}
```



Здесь для примера добавляем несколько ключей. Причем специально пытаемся добавить больше ключей, чем может вместить таблица. Затем выводим таблицу с помощью примитивной функции вывода print_table и затем проверям наличие одной из них в хеш-таблице - до и после удаления. Затем повторно проверяем состояние всей таблицы. В итоге мы получим следующий вывод:



```bash

Unable to insert the key `1452231588`. No free bins
Unable to insert the key `3724674918`. No free bins

1089765596 - 18738364 - 2197550541 - 96429129

string `red` is present
delete key 1089765596
string `red` is absent

0 - 18738364 - 2197550541 - 96429129
```



### Послесловие



При реализации хеш-таблиц неизбежно возникает вопрос, какую стратегию разрешения коллизий выбрать. Самым простым и, возможно, логичным видится метод цепочек, то есть применение связанных списков. И лучший способ, как всегда, - это тестирование сравниваемых стратегий при реализации конкретной задачи при конкретных условиях. Тем не менее есть несколько аспектов. В частности, поскольку ячейки в таблицах с открытой адресацией размещаются в смежных областях памяти, производительность кэширования, вероятно, будет выше. Если все ячейки помещаются в одну строку кэша, открытая адресация очень эффективна. Но даже если нет, линейное зондирование на небольших хеш-таблицах приведет к меньшему количеству промахов кэша. При линейном зондировании обращение идет к близлежащим областям памяти, что оптимально для эффективности кэширования. При двойном хешировании происходит перемещение по памяти, поэтому следует ожидать большего количества промахов кэша. Хотя при линейном зондировании длина последовательности может быть больше, чем скажем при двойном хешировании или при проходе по связанному списку при методе цепочек, но улучшенная производительность кэша может компенсировать это, особенно когда максимальное количество элементов ограничено размером таблицы.

Несмотря на то что метод цепочек позволяет добавлять бесконечное количество элементов в одну корзину, используя связанные списки, расширение хеш-таблицы позволяет увеличить ее главного преимущество - скорость. Смысл в подобном расширении заключается в поддержании константного времени доступа `O(1)`. В частности, следует учитывать следующие аспекты:





- Производительность : если количество элементов ( n ) значительно превышает количество корзин ( m ), средняя длина списков растет. В итоге поиск превращается в линейный перебор списка, и скорость падает с O(1) до O(n) .

- Коэффициент заполнения (Load Factor): для цепочек оптимальным считается alpha = n/m в пределах 0.75–1.0 . Когда это значение превышается, это может быть сигналом к увеличению таблицы (обычно в 2 раза) и проводить перехеширование (rehashing), чтобы распределить элементы по новым корзинам и снова укоротить списки.

- Худший случай : без расширения даже при хорошей хеш-функции мы рискуем получить "вырожденную" таблицу, которая по сути станет одним длинным связным списком.



То есть в данном случае расширение нужно не для того, чтобы новые элементы влезли в хеш-таблицу (как в методе открытой адресации), а для того, чтобы все работало быстро.



#### Аспекты реализации



В качестве отправной точки возьмем код работы с хеш-таблицами по методу цепочки и рассмотрим те моменты, которые будут отличаться. А в конце я приведу общий код с простейшим примером работы.



Во-первых, необходимо отслеживать количество корзин и количество ключей, которые хранятся в таблице. Для этого в структуре хеш-таблицы определим два поля: количество корзин и количество элементов, которые хранятся в этих корзинах:



```c

// отдельный элемент корзины
struct node 
{
    unsigned int key;
    struct node* next;
};
// определение корзины
typedef struct node **BIN;

// структура хеш-таблицы
struct hash_table 
{
    struct node** bins;
    unsigned int size;  // общее количество корзин
    unsigned int count;  // количество добавленных элементов (НЕ корзин!)
};
```



При создании таблицы инициализируем ее минимальным количеством ячеек (MIN_SIZE),и сохраняем это значение в ее размере:



```c

#define MIN_SIZE 8

void init_bins(struct hash_table* table)
{
    // для всех ячеек устанавливаем в качестве значения устанавливаем NULL
    for (BIN bin = table->bins; bin < table->bins + table->size; bin++) 
    {
        *bin = NULL;
    }
}
struct hash_table* new_table()
{
    struct hash_table *table = malloc(sizeof *table);
    struct node** bins = malloc(MIN_SIZE * sizeof *bins);
    *table = (struct hash_table){.bins = bins, .size = MIN_SIZE, .count = 0};
    init_bins(table);   // инициализация всех корзин таблицы
    return table;
}
```



При изменении размера необходимо выделить новый массив для ячеек, а затем скопировать все данные из старых ячеек в новые. Этот процесс можно разделить на две функции. Первая функция выделяет новые ячейки и вызывает вторую для перемещения данных:



```c

// копирование корзин и их узлов, from - указатель на первую корзину, to - указатель на последнюю
void copy_nodes(struct hash_table* table, BIN from, BIN to)
{
    // проходим от from до to
    for (; from < to; from++) 
    {
        // пока не дойдем до указателя на node, который равен NULL
        while (*from) 
        {
            struct node* node = *from;
            // удаляем первый узел из старой корзины и заменяем его на next
            *from = node->next;
            // помещаем узел в новую корзину
            BIN new_bin = get_bin(table, node->key);
            node->next = *new_bin;
            *new_bin = node;
        }
    }
}
// изменение размера
void resize(struct hash_table* table, unsigned int new_size)
{

    struct node **old_bins = table->bins,        // получаем старые корзины
                **old_from = old_bins,              // начальная позиция для копирования
                **old_to = old_from + table->size;  // конечная позиция для копирования
    // выделяем память под новую таблицу
    table->bins = malloc(new_size * sizeof *table->bins);
    table->size = new_size;
    init_bins(table);
    // копируем данные из старых корзин в новые
    copy_nodes(table, old_from, old_to);
    // освобождаем память корзин старой хеш-таблицы
    free(old_bins);
}
```



Функция copy_nodes принимает хеш-таблицу, указатель на первую корзину - from (указатель на указатель на node) и указатель на последнюю корзину, и копирует все элементы из старой корзины в новую. А функция resize получает копируемую хеш-таблицу и новый размер, получает старые корзины и, используя функцию copy_nodes, копирует данные в новые корзины.




Изменять размер можно, например, каждый раз при вставке или удалении ключа:



```c

// вставка ключа
void insert_key(struct hash_table* table, unsigned int key)
{
    // получаем корзину
    BIN bin = get_bin(table, key);
    if (!contains_node(bin, key)) 
    {
        add_node(bin, key);
        table->count++;
        // если в таблице количество элементов равно количеству корзин
        // то изменяем размер
        if (table->size == table->count) 
        {
            resize(table, 2 * table->size);
        }
    }
}
// удаление ключа 
void delete_key(struct hash_table* table, unsigned int key)
{
    BIN bin = get_bin(table, key);
    if (contains_node(bin, key)) 
    {
        free_node(bin, key);
        table->count--;
        // если в таблице количество элементов - четверть от количества корзин
        // то изменяем размер
        if (table->size > MIN_SIZE && table->count < table->size / 4) 
        {
            resize(table, table->size / 2);
        }
    }
}
```



Перед вставкой/удалением ключа сначала необходимо проверить, находится ли нужный ключ в таблице. И если да, то изменение размера происходит после вставки или удаления. ПРи вставке расширяем таблицу, если в таблице количество элементов равно количеству корзин. При удалении сужаем таблицу, если в таблице количество элементов - четверть от количества корзин.



#### Полный пример



Полный пример кода для работы с хеш-таблицей с учетом ее расширения мог бы выглядеть следующим образом:



```c

#include <stdio.h>
#include <stdlib.h>

// минимальное количество корзин
#define MIN_SIZE 8

// отдельный элемент корзины
struct node 
{
    unsigned int key;
    struct node* next;
};
// определение корзины
typedef struct node** BIN;

// структура хеш-таблицы
struct hash_table 
{
    struct node** bins;
    unsigned int size;  // общее количество корзин
    unsigned int count;  // количество добавленных элементов (НЕ корзин!)
};

// создаем новый узел в корзине
struct node* new_node(unsigned int key, struct node *next)
{
    struct node *node = malloc(sizeof *node);
    *node = (struct node){.key = key, .next = next};
    return node;
}
// добавляем новый узел в корзину
void add_node(BIN bin, unsigned int key)
{
    *bin = new_node(key, *bin);
}

// поиск ключа в корзине
BIN find_key(BIN bin, unsigned int key)
{
    for (; *bin; bin = &(*bin)->next) 
    {
        if ((*bin)->key == key) return bin;
    }
    return NULL;
}
// проверка наличия элемента
int contains_node(BIN bin, unsigned int key)
{
    return find_key(bin, key) != NULL;
}
// удаляем начало (голову) корзины
void free_head(BIN bin)
{
    struct node *next = (*bin)->next;
    free(*bin);
    *bin = next;
}

// удаление элемента
void free_node(BIN bin, unsigned int key)
{
    if ((bin = find_key(bin, key))) 
    {
        free_head(bin);
    }
}

// удаляем всю корзину
void free_bin(BIN bin)
{
    while (*bin) 
    {
        free_head(bin);
    }
}

// инициализация корзин
void init_bins(struct hash_table* table)
{
    // для всех ячеек устанавливаем в качестве значения устанавливаем NULL
    for (BIN bin = table->bins; bin < table->bins + table->size; bin++) 
    {
        *bin = NULL;
    }
}
// создание новой таблицы
struct hash_table* new_table()
{
    struct hash_table *table = malloc(sizeof *table);
    struct node** bins = malloc(MIN_SIZE * sizeof *bins);
    *table = (struct hash_table){.bins = bins, .size = MIN_SIZE, .count = 0};
    init_bins(table);   // инициализация всех корзин таблицы
    return table;
}
// удаление хеш-таблицы
void free_table(struct hash_table *table)
{
    for (BIN bin = table->bins; bin < table->bins + table->size; bin++) 
    {
        free_bin(bin);
    }
    free(table->bins);
    free(table);
}
// получение корзины в хеш-таблице
BIN get_bin(struct hash_table *table, unsigned int key)
{
    unsigned int mask = table->size - 1;
    unsigned int index = key & mask;
    return table->bins + index;
}


void copy_nodes(struct hash_table* table, BIN from, BIN to)
{
    // проходим корзины от from до to
    for (; from < to; from++) 
    {
        // пока не дойдем до указателя на node, который равен NULL
        while (*from) 
        {
            struct node* node = *from;
            // удаляем первый узел из старой корзины и заменяем его на next
            *from = node->next;
            // помещаем узел в новую корзину
            BIN new_bin = get_bin(table, node->key);
            node->next = *new_bin;
            *new_bin = node;
        }
    }
}

void resize(struct hash_table* table, unsigned int new_size)
{

    struct node **old_bins = table->bins,           // получаем старые корзины
                **old_from = old_bins,              // начальная позиция для копирования
                **old_to = old_from + table->size;  // конечная позиция для копирования
    // выделяем память под новую таблицу
    table->bins = malloc(new_size * sizeof *table->bins);
    table->size = new_size;
    init_bins(table);
    // копируем данные из старыз корзин в новые
    copy_nodes(table, old_from, old_to);
    // освобождаем память корзин старой хеш-таблицы
    free(old_bins);
}


// добавление данных в хеш-таблицу
void insert_key(struct hash_table* table, unsigned int key)
{
    // получаем корзину
    BIN bin = get_bin(table, key);
    if (!contains_node(bin, key)) 
    {
        add_node(bin, key);
        table->count++;
        // если в таблице количество элементов равно количеству корзин
        // то изменяем размер
        if (table->size == table->count) 
        {
            resize(table, 2 * table->size);
        }
    }
}
// удаление ключа
void delete_key(struct hash_table* table, unsigned int key)
{
    BIN bin = get_bin(table, key);
    if (contains_node(bin, key)) 
    {
        free_node(bin, key);
        table->count--;
        // если в таблице количество элементов - четверть от количества корзин
        // то изменяем размер
        if (table->size > MIN_SIZE && table->count < table->size / 4) 
        {
            resize(table, table->size / 2);
        }
    }
}
// проверка наличия данных
int contains_key(struct hash_table *table, unsigned int key)
{
    return contains_node(get_bin(table, key), key);
}
// получаем хеш-значение из строки
unsigned int hash_fnv1a(const char *str) 
{
   unsigned int hash = 2166136261u;

    while (*str) {
        hash ^= (unsigned char)(*str++);
        hash *= 16777619;
    }

    return hash;
}

// примитивная функция для вывода хеш-таблицы
void print_table(struct hash_table* table)
{
    for (int i =0; i < table->size; ++i) 
    {
        BIN bin = table->bins + i;
        // выводим все ключи текущей корзины
        printf("bin %d: ", i);
        for (; *bin; bin = &(*bin)->next) 
        {
            printf("%u, ", (*bin)->key);
        }

        putchar(10);
    }
}

int main(void)
{
    struct hash_table* dict = new_table();

    // строки для примера
    char* colors[] = {"red", "green", "blue", "yellow", "violet", "rose", "black", "white"};
    for(int i =0; i < sizeof(colors)/sizeof(colors[0]); i++)
    {
        // получаем хеш строк
        unsigned int hash = hash_fnv1a(colors[i]);
        // добавляем строки в хеш-таблицу
        insert_key(dict, hash);
    }
    print_table(dict);
    // получаем хеш строки `red`
    unsigned int red_hash = hash_fnv1a(colors[0]); 

    // проверим, есть ли строка red в таблице
    int is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем строку `red` из хеш-таблицы
    delete_key(dict, red_hash);

    // снова проверяем, есть ли строка в хеш-таблице
    is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем всю хеш-таблицу
    free_table(dict);

    return 0;
}
```



В данном случае в качестве примера добавляем все строки массива colors в хеш-таблицу, выводим ее содержимое с помощью простейшей функции print_table и затем проверяем два раза наличие ключа в таблицы - до и после его удаления.

Общий принцип изменения размера хеш-таблиц одинаков для разных стратегий. После каждой операции вставки или удаления сравниваем количество занятых ячеек с общим количеством ячеек хеш-таблицы. И если требуется изменение размера, выделяем память под новый массив ячеек, инициализируем его и копируем все элементы из старого массива в новый. Однако детали будут немного различаться между стратегией цепочки и открытой адресацией. Расширение хеш-таблицы при открытой адресации имеет сложность: удаленные элементы все еще занимают место в таблице, чтобы сохранить последовательность зондирования. Так, ранее в предыдыдущих темах для описания хеш-таблицы мы использовали следующие структуры:



```c

// ячейка хеш-таблицы
struct bin 
{
    unsigned int key;
    int in_probe : 1;   // является ли частью последовательности зондирования
    int is_empty : 1;   // пустая ли ячейка
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;
};
```



Структура bin имела два специальных флага: in_probe (является ли частью последовательности зондирования) и is_empty (пустая ли ячейка) При удалении элемента его ячейка помечается как "свободная" (`is_empty = 1`), но он все равно будет частью цепочки зондирования (`in_probe = 1`). Таким образом, при поиске свободной ячейки нагрузка уменьшается, так как нам не надо доходить до конца последовательности зондирования, чтобы найти свободную ячейку - эта ячейка внутри последовательности зондирования. Однако если мы ищем какой-то определенный ключ, то нагрузка не уменьшается. Таким образом, удаленные элементы замедляют поиск ключей, проверку из наличия в таблице, и, следовательно, операции вставки и удаления так же сильно, как и ключи, которые все еще находятся в таблице.




Основная проблема при изменении размера хеш-таблиц при открытой адресации состоит в том, что мы не можем уменьшать счетчик количества ключей при их удалении - так как эти ключи все еще являются частью последовательности зондирования. И чтобы определить, когда следует увеличивать размер таблицы для обеспечения хорошей производительности, нам надо учитывать как общее количество ключей в таблице, так и количество удаленных элементов:



```c

// ячейка хеш-таблицы
struct bin 
{
    unsigned int key;
    int in_probe : 1;   // является ли частью последовательности зондирования
    int is_empty : 1;   // пустая ли ячейка
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;      // общий размер таблицы
    unsigned int count;     // общее количество элементов (удаленных и неудаленных)
    unsigned int active;    // количество активных (неудаленных) элементов
};
```



Первый счетчик в структуре хеш-таблицы - count, подсчитывает, сколько ячеек входят в состав последовательности зондирования - либо потому, что ячейка содержит ключ, либо потому, что в ней хранится ранее удаленный ключ. Второй счетчик - active - указывает, сколько ячеек содержат фактический ключ.



### Создание и удаление хеш-таблицы



Для создания хеш-таблицы можно использовать следующую функцию:



```c

#define MIN_SIZE 4  // минимальный размер хеш-таблицы
// функция инициализации таблицы
init_table(struct hash_table* table, unsigned int size, struct bin* begin, struct bin* end);
// создание таблицы
struct hash_table* new_table()
{
    struct hash_table *table = malloc(sizeof *table);
    init_table(table, MIN_SIZE, NULL, NULL);
    return table;
}
```



При создании хеш-таблицы применяется функция `init_table()`, которая инициализирует хеш-таблицу и выделяет ячейки размером, указанным в качестве второго аргумента. Третий и четвертый аргументы используются при изменении размера таблицы. Поскольку эта функция зависит от других функций, то мы ее определим позже, а пока что будет достаточно указать прототип.



А для удаления следующую функцию:



```c

void free_table(struct hash_table *table)
{
    free(table->bins);
    free(table);
}
```



### Поиск ячеек



Функции поиска ячейки с определенным ключом и свободной ячейки остаются теми же, что и раньше:



```c

// функция зондирования - линейное зондирование
unsigned int p(unsigned int key, unsigned int i, unsigned int m)
{
    return (key + i) & (m - 1);
}

// поиск ячейки с определенным ключом
struct bin* find_key(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin* bin = table->bins + p(key, i, table->size);

        // если хеш равен искомому, а яйчека не является пустой
        // возвращаем данную ячейку
        if (bin->key == key && !bin->is_empty) return bin;
    }
    return NULL;  // если ничего не нашли
}
// поиск пустой ячейки
struct bin* find_empty(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + p(key, i, table->size);
        // если ячейка пуста, возвращаем ее
        if (bin->is_empty) return bin;
    }
    // поскольку при добавлении таблица будет расширяться,
    // то невозможна ситуация, когда у нас не будет пустых ячеек
}
```



Поскольку заполнения таблицы теперь не происходит (при необходимости она расширяется), то при поиске в `find_empty()` мы всегда найдем пустую ячейку, потому нет смысла возвращать какое-либо альтернативное значение, типа NULL, или генерировать какую-либо ошибку.



Проверка наличия ключа будет выглядеть как и раньше - проверяем, что ячейка найдена и что она не равна NULL:



```c

int contains_key(struct hash_table* table, unsigned int key)
{
    return find_key(table, key);
    return bin != 0;
}
```



### Вставка ключей



При вставке ключа необходимо учитывать три случая:





- Добавляемый ключ уже находится в таблице. В этом случае поля-счетчики в структуре ( count и active ) остаются без изменений. Также не требуется проверка необходимости изменения размера таблицы, поскольку с момента последнего обновления ничего не изменилось.

- Добавляемый ключ вставляется в пустую ячейку. В этом случае возможны два варианта: Пустая ячейка является частью последовательности зондирования. В этом случае необходимо увеличить количество активных ячеек ( active ), но а общее количество используемых ячеек ( count ) остается неизменным - ячейка ведь уже использовалась.

- Пустая ячейка НЕ является частью последовательности зондирования. Тогда необходимо увеличить как количество активных ( active ), так и общее количество используемых ячеек ( count ).


 



Кроме того, после вставки ключа необходимо проверить, превышает ли загрузка половину, и если да, то увеличить размер таблицы вдвое. Для вставки мы могли бы определить следующую функцию:



```c

void insert_key(struct hash_table* table, unsigned int key)
{
    // если таблица содержит ключ, выходим из функции
    if (contains_key(table, key)) return;

    // иначе ищем пустую ячейку для вставки
    struct bin* key_bin = find_empty(table, key);
    // поскольку мы в любом случае найдем ячейку, увеличиваем количество активных ячеек
    table->active++;
    // если ячейка НЕ является частью последовательности зондирования
    if (!key_bin->in_probe) table->count++;  // значит, это ранее неиспользованная ячейка
    // устанавливаем содержимое ячейки
    *key_bin = (struct bin){.in_probe = 1, .is_empty = 0, .key = key};
    // при необходимости изменяем размер
    if (table->count > table->size / 2) resize(table, table->size * 2);
}
```



### Инициализация таблицы



Определим функцию инициализации ячеек хеш-таблицы:



```c

void init_table(struct hash_table *table, unsigned int size, struct bin* begin, struct bin* end)
{
    // выделяем память для новых ячеек и инициализируем поля структуры хеш-таблицы
    struct bin* bins = malloc(size * sizeof *bins);
    *table = (struct hash_table){.bins = bins, .size = size, .count = 0, .active = 0};

    // инициализируем ячейки (по умолчанию все ячейки пусты и не в последовательности зондирования)
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < table->size; i++) 
    {
        table->bins[i] = empty_bin;
    }

    // копируем данные из старых ячеек в новую таблицу
    for (struct bin *bin = begin; bin != end; bin++) 
    {
        // ячейка должна быть не пустой
        if (!bin->is_empty) 
        {
            insert_key(table, bin->key);
        }
    }
}
```



Функция `init_table()` выделяет ячейки и инициализирует их как пустые, а затем проходит по старым ячейкам и с помощью вызова `insert_key()` из каждой непустой ячейки копирует данные в новую таблицу. Поскольку таблица инициализируется значениями `count = 0` и `active = 0`, вставка ключей таким образом обеспечивает необходимый учет.




### Удаление ключа



При удалении, если ключ еще не находится в таблице, ничего не происходит. Иначе ключ удаляется, соответственнл необходимо уменьшить количество активных ячеек (`active`). Однако обшее количество ячеек (`count`) остается неизменным, поскольку ячейка с удаляемым ключом все еще является частью последовательности зондирвания:



```c

vvoid delete_key(struct hash_table* table, unsigned int key)
{
    // находим ячейку с удаляемым ключом
    struct bin* bin = find_key(table, key);

    // если таблица НЕ содержит ключ, выходим из функции
    if (!bin) return;

    printf("delete key %u\n", key);
    bin->is_empty = 1;  // ячейка теперь свободна
    table->active--;    // количество активных ячеек уменьшается
    // при необходимости уменьшаем размер
    if (table->active < table->size / 8 && table->size > MIN_SIZE) 
        resize(table, table->size / 2);
}
```



После удаления проверяем, не пора ли изменить размер таблицы - если нагрузка меньше 1/8, а размер таблицы превышает минимальный.



### Изменение размера



Функция изменения размера относительно проста, поскольку основная работа выполняется в функции `init_table()`:



```c

void resize(struct hash_table *table, unsigned int new_size)
{
    
    struct bin *old_bins_begin = table->bins,                   // указатель на начало старых ячеек
                *old_bins_end = old_bins_begin + table->size;   // указатель на конец старых ячеек
    // обновляем таблицу и копируем в нее старые данные
    init_table(table, new_size, old_bins_begin, old_bins_end);
    // освобождаем память старых ячеек
    free(old_bins_begin);
}
```



Эта функция получает диапазон старых ячеек и передает его в виде двух переменных в `init_table()`. А `init_table()` выполняет основную работу: выделяет новые ячейки и копирует в них данные из старых ячеек. И после копирования освобождаем память старых ячеек.



### Пример работы с хеш-таблицами



Соберем все вместе и посмотрим на простейшем примере работу хеш-таблицы:



```c

#include <stdio.h>
#include <stdlib.h>

#define MIN_SIZE 4  // минимальный размер хеш-таблицы

// ячейка хеш-таблицы
struct bin 
{
    unsigned int key;
    int in_probe : 1;   // является ли частью последовательности зондирования
    int is_empty : 1;   // пустая ли ячейка
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;      // общий размер таблицы
    unsigned int count;     // общее количество элементов (удаленных и неудаленных)
    unsigned int active;    // количество активных (неудаленных) элементов
};

// функция инициализации таблицы
void init_table(struct hash_table* table, unsigned int size, struct bin* begin, struct bin* end);
// создание хеш-таблицы
struct hash_table* new_table()
{
    struct hash_table *table = malloc(sizeof *table);
    init_table(table, MIN_SIZE, NULL, NULL);
    return table;
}

// удаление таблицы
void free_table(struct hash_table *table)
{
    free(table->bins);
    free(table);
}
// линейное зондирование
unsigned int p(unsigned int key, unsigned int i, unsigned int m)
{
    return (key + i) & (m - 1);
}

// поиск ячейки с определенным ключом
struct bin* find_key(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin* bin = table->bins + p(key, i, table->size);

        // если хеш равен искомому, а яйчека не используется в зондировании
        // возвращаем данную ячейку
        if (bin->key == key && !bin->is_empty) return bin;
    }
    return NULL;  // если ничего не нашли
}
// поиск пустой ячейки
struct bin* find_empty(struct hash_table* table, unsigned int key)
{
    // проходим по ячейкам таблицы
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + p(key, i, table->size);
        // если ячейка пуста, возвращаем ее
        if (bin->is_empty) return bin;
    }
    // поскольку при добавлении таблица будет расширяться,
    // то невозможна ситуация, когда у нас не будет пустых ячеек
}

// проверка наличия ключа 
int contains_key(struct hash_table* table, unsigned int key)
{
    struct bin *bin = find_key(table, key);
    return bin != 0;
}

// изменение размера таблицы
void resize(struct hash_table *table, unsigned int new_size)
{
    struct bin *old_bins_begin = table->bins,                   // указатель на начало старых ячеек
                *old_bins_end = old_bins_begin + table->size;   // указатель на конец старых ячеек
    // обновляем таблицу и копируем в нее старые данные
    init_table(table, new_size, old_bins_begin, old_bins_end);
    // освобождаем память старых ячеек
    free(old_bins_begin);
}

// удаление ключа
void delete_key(struct hash_table* table, unsigned int key)
{
    // находим ячейку с удаляемым ключом
    struct bin* bin = find_key(table, key);

    // если таблица НЕ содержит ключ, выходим из функции
    if (!bin) return;

    bin->is_empty = 1;  // ячейка теперь свободна
    table->active--;    // количество активных ячеек уменьшается
    // при необходимости уменьшаем размер
    if (table->active < table->size / 8 && table->size > MIN_SIZE) 
        resize(table, table->size / 2);
}

// добавление ключа
void insert_key(struct hash_table* table, unsigned int key)
{
    // если таблица содержит ключ, выходим из функции
    if (contains_key(table, key)) return;

    // иначе ищем пустую ячейку для вставки
    struct bin* key_bin = find_empty(table, key);
    // поскольку мы в любом случае найдем ячейку, увеличиваем количество активных ячеек
    table->active++;
    // если ячейка НЕ является частью последовательности зондирования
    if (!key_bin->in_probe) table->count++;  // значит, это ранее неиспользованная ячейка
    // устанавливаем содержимое ячейки
    *key_bin = (struct bin){.in_probe = 1, .is_empty = 0, .key = key};
    // при необходимости изменяем размер
    if (table->count > table->size / 2) resize(table, table->size * 2);
}

// инициализация хеш-таблицы
void init_table(struct hash_table* table, unsigned int size, struct bin* begin, struct bin* end)
{
    // выделяем память для новых ячеек и инициализируем поля структуры хеш-таблицы
    struct bin* bins = malloc(size * sizeof *bins);
    *table = (struct hash_table){.bins = bins, .size = size, .count = 0, .active = 0};

    // инициализируем ячейки (по умолчанию все ячейки пусты и не в последовательности зондирования)
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < table->size; i++) 
    {
        table->bins[i] = empty_bin;
    }

    // копируем данные из старых ячеек в новую таблицу
    for (struct bin *bin = begin; bin != end; bin++) 
    {
        // ячейка должна быть не пустой
        if (!bin->is_empty) 
        {
            insert_key(table, bin->key);
        }
    }
}


// получаем хеш-значение из строки алгоритмом FNV-1a
unsigned int hash_fnv1a(const char *str) 
{
   unsigned int hash = 2166136261u;

    while (*str) {
        hash ^= (unsigned char)(*str++);
        hash *= 16777619;
    }

    return hash;
}

// вывод хеш-таблицы
void print_table(struct hash_table* table)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        // получаем ячейку по индексу
        struct bin *bin = table->bins + i;
        // просто выводим все ключи из непустых ячеек в строчку
        printf("%u", bin->is_empty?0:bin->key);
        if(i < table->size-1) printf(" - ");
    }
    putchar(10);
}

int main(void)
{
    struct hash_table* dict = new_table();

    // строки для примера
    char* colors[] = {"red", "green", "blue", "yellow", "violet", "rose", "black", "white"};
    for(int i =0; i < sizeof(colors)/sizeof(colors[0]); i++)
    {
        // получаем хеш строк
        unsigned int hash = hash_fnv1a(colors[i]);
        // добавляем строки в хеш-таблицу
        insert_key(dict, hash);
    }
    // выводим содержимое
    print_table(dict);

    // получаем хеш строки `red`
    unsigned int red_hash = hash_fnv1a(colors[0]); 

    // проверим, есть ли строка red в таблице
    int is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // удаляем строку `red` из хеш-таблицы
    printf("delete key %u\n", red_hash);
    delete_key(dict, red_hash);

    // снова проверяем, есть ли строка в хеш-таблице
    is_present = contains_key(dict, red_hash);
    printf("string `red` is %s\n", is_present?  "present" : "absent");

    // снова выводим содержимое для проверки
    print_table(dict);

    // удаляем всю хеш-таблицу
    free_table(dict);
    return 0;
}
```



В данном случае в качестве примера добавляем все строки массива colors в хеш-таблицу, выводим ее содержимое с помощью простейшей функции print_table и затем проверяем два раза наличие ключа в таблицы - до и после его удаления.



В итогн мы получим консольный вывод наподобие:



```bash

0 - 0 - 2070763506 - 0 - 1452231588 - 0 - 272766982 - 3724674918 - 0 - 96429129 - 0 - 0 - 1089765596 - 18738364 - 2197550541 - 0
string `red` is present
delete key 1089765596
string `red` is absent
0 - 0 - 2070763506 - 0 - 1452231588 - 0 - 272766982 - 3724674918 - 0 - 96429129 - 0 - 0 - 0 - 18738364 - 2197550541 - 0
```

При изменении размера хеш-таблицы, когда ее начальный размер не является степенью двойки, а является, к примеру, простым числом, все становится несколько сложнее. Для увеличения и уменьшения размера таблицы в два раза можно ввести еще один параметр - `β` и установить размер таблицы равным `β * m` при расширении таблицы и `m/β` при ее уменьшении, где `m` - начальный размер таблицы. Однако, проблема в том, что выражения `β * m` и `m/β` необязательно дадут другое простое число.

В качестве решения мы можем выбрать простые числа, близкие к этому значению (`β * m` и `m/β`), и составить таблицу простых чисел `p 1 , p 2 , ..., p N` таким образом, чтобы `p j-1 β*p j`.

Так, мы можем добавить таблицу простых чисел, основанную на выбранном вами значении β. Например, при β = 2 мы можете определить таблицу простых чисел следующим образом:

```c
// таблица простых чисел
int primes[] = 
{
    2, 5, 11, 23, 47, 97, 197, 397,
    797, 1597, 3203, 6421, 12853, 25717, 51437,
    102877, 205759, 411527, 823117, 1646237,
    3292489, 6584983, 13169977 
};
// количество простых чисел
unsigned int primes_num = sizeof(primes)/sizeof(int);
```

Теоретически можно, конечно, вычислять нужное простое число динамически, но это может быть довольно затратная операция. Использование готового набора с индексацией по этому набору облегчает работу и увеличивает производительность. Готовые списки простых чисел можно посмотреть по адресу [https://t5k.org/lists/](https://t5k.org/lists/)

Для работы с размерами и таблицей простых чисел в структуру хеш-таблицы можно добавить специальное поле, которое будет представлять индекс простого числа в таблице простых чисел:

```c
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;       // массив ячеек таблицы
    unsigned int size;      // общий размер таблицы
    unsigned int count;     // общее количество элементов (удаленных и неудаленных)
    unsigned int active;    // количество активных (неудаленных) элементов
    unsigned int prime;     // индекс простого числа в таблице простых чисел
};
```

При вставке ключа (функция insert_key из прошлых статей) мы можем расширять таблицу следующим образом:

```c
if (table->count > table->size / 2) 
{
    assert(table->prime + 1 < primes_num );
    resize(table, primes[table->prime + 1]);
    table->prime = table->prime + 1;
}
```

Здесь в качестве фактора применяется `β = 2`. И если текущее количество превышает значение `m/β`, то с помощью `assert()` проверяем, что в таблице простых чисел есть индекс `prime + 1`. И, если есть, используем число по этому индексу в качестве нового размера.

Для удаления ключа (функция delete_key из прошлых статей) мы можем использовать следующие действия:

```c
if (table->active < table->size / 8 && table->prime > 0) 
{
    resize(table, primes[table->prime - 1]);
    table->prime = table->prime - 1;
}
```

В прошлой теме было рассмотрено создание универсальных хеш-таблиц с помощью макросов. Однако написание макросов для генерации кода и использование представляет непростую задачу, которая чревата ошибками, а написанный код труден в отладке. Кроме того, макросы могут приводить к раздуванию бинарного кода. Но есть альтернативный подход к написанию универсальных хеш-таблиц - использование единственного универсального типа, который есть в языке C -указатель типа void . И именно этот подход мы и рассмотрим в данной статье.



Стандарт языка гарантирует, что переменной типа `void*` можно присвоить указатель любого типа, и что любой переменной типа указатель можно присвоить указатель типа `void*`. Это означает, что мы можем писать код с использованием объектоа типа `void*`, и этот код может обрабатывать любые другие типы указателей.



Недостатком этого подхода является то, что здесь нет проверки типов по умолчанию, то есть вы можете присвоить значение типа `int*` переменной типа `void*`, а затем ее значение переменной типа `char*` и никаких проблем с типами не возникнет, однако во время выполнения можно столкнуться со значительными проблемами.



Другой недостаток - такой подход работает только с указателями. Допустим, вам нужно преобразовать строки в целые числа. Строки уже являются указателями, `char*`, поэтому с ними проблем нет, но любое целое число необходимо преобразовать в `int*`. Если у вас есть переменная `i`, вы можете использовать `&i`, но для литерала, например, 26, вам понадобятся уловки, такие как `&(int){26}`:



```c

void* p_v = &(int){26};
int* p_i = p_v;
printf("i: %d\n", *p_i); // i: 26
```



Но в обоих случаях необходимо убедиться, что вставляемое в таблицу значение не изменяется, иначе механизм хеширования не сможет найти его снова. Это означает, что вы не можете снова присвоить значение переменной i, если указатель вставлен без изменений, и, вероятно, вы не можете снова создать выражение &(int){literal}, поскольку компиляторы, как правило, повторно используют свою память. Поэтому распространенное решение состоит в том, что копировать непосрественно в хеш-таблицу хранимые значения, чтобы хеш-таблица была их владельцем.




Поскольку обычно невозможно знать, как копировать, сравнивать и освобождать ключи и значения, необходимо предоставить пользователю механизм, который позволяет ему самому настроить подобный функционал. Суть механизма состоит в том, что передавать указатели на функции, которые реализуют необходимые операции:



```c

// тип для функции хеширования
typedef unsigned int (*hash_func)(void const *);
// тип для функции сравнения
typedef int (*compare_func)(void const *, void const *);
// тип для функции освобождения памяти
typedef void (*destructor_func)(void *);
// тип для функции копирования данных
typedef void *(*copy_func)(void const *);
```



Далее мы можем определить структуры для типов ключей и значений, которые принимают эти указатели:



```c

// тип ключей
struct key_type 
{
    hash_func hash;
    compare_func cmp;
    copy_func cpy;
    destructor_func del;
};
// тип значений
struct value_type 
{
    copy_func cpy;
    destructor_func del;
};
```



То есть нам надо уметь вычислять хеш-значение и сравнивать два ключа, а также уметь копировать и освобождать данные как для ключей, так и для значений.




Далее определим прототипы для базовых операций с хеш-таблицей:



```c

// создание хеш-таблицы
struct hash_table* new_table(struct key_type const *key_type, struct value_type const *value_type);
// удаление хеш-таблицы
void delete_table(struct hash_table *table);
// добавление клча и значения
void add(struct hash_table *table, void const *key, void const *value);
// удаление данных
void delete_key(struct hash_table *table, void const *key);
// поиск данных
void *const lookup_key(struct hash_table *table, void const *key);
```



Объявления `const` указывают на то, что мы не будем присваивать себе права собственности на ключи и значения.



### Определение хеш-таблицы



В качестве стратегии реализации хеш-таблицы возьмем стратегию линейного зондирования. Структуры ячейки и самой хеш-таблицы будут выглядеть следующим образом:



```c

// структура ячейки хеш-таблицы
struct bin 
{
    int in_probe : 1;       // является ли ячейка частью последовательности зондирования
    int is_empty : 1;       // является ли ячейка пустой
    unsigned int hash_key;  // хеш-ключ
    void *key;              // указатель на ключ
    void *val;              // указатель на значение
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;
    unsigned int count;
    unsigned int active;
    struct key_type const *key_type;
    struct value_type const *value_type;
};
```



В принципе эти структуры во многом похожи на те, что использовались в прошлых статьях при рассмотрении стратегии линейного зондирования. За тем исключением, что структура ячейки также содержит указатели на ключ и значение, которые надо сохранить, а структура хеш-таблицы будет содержит указатель на определения функций key_type и value_type для управления ключами и значениями в ячейках.




Поскольку мы будем использовать линейное зондирование, то определим следующую функцию зондирования:



```c

// линейное зондирование
unsigned int p(unsigned int key, unsigned int i, unsigned int m)
{
    return (key + i) & (m - 1);
}
```



### Вспомогательные функции



Для упрощения вызова операций добавим несколько вспомогательных функций. Прежде всего определим хеш-функцию, которая использует хеш-функцию типа ключа для сопоставления пользовательского ключа с хеш-ключом:



```c

unsigned int hash(struct hash_table *table, void const *key)
{
    return table->key_type->hash(key);
}
```



Для копирования ключей и значений (key и value) опредлим соответственно функции copy_key и copy_val:



```c

// копирование ключей
void* copy_key(struct hash_table *table, void const *key)
{
    return table->key_type->cpy(key);
}
// копирование значений
void* copy_val(struct hash_table *table, void const *val)
{
    return table->value_type->cpy(val);
}
```



Аналогично определим функции free_key и free_val для освобождения памяти ключей и значений:



```c

void free_key(struct hash_table *table, void *key)
{
    table->key_type->del(key);
}
void free_val(struct hash_table *table, void *val)
{
    table->value_type->del(val);
}
```



И последняя вспомогательная функция - is_active_bin будет проверять, активна ли ячейка таблицы в данный момент (является ли она частью последовательности зондирования и при этом не является пустой):



```c

int is_active_bin(struct bin *bin)
{
    return bin->in_probe && !bin->is_empty;
}
```



### Создание таблицы и изменение размера



Для инициализации таблиц и их обновления при изменении размера определим функцию `init_table()`:



```c

// вспомогательная функция для добавления данных
// на вход получает хеш-ключ и копирует ключ и значение, вставляя данные в таблицу
void add_internal(struct hash_table *table, unsigned int hash_key, void *key_copy, void *value_copy);
// Инициализирует таблицу и затем копирует ячейки из begin в end
void init_table(struct hash_table *table, unsigned int size, struct bin *begin, struct bin *end)
{
    // инициализация полей структуры
    table->bins = malloc(size * sizeof *table->bins);
    table->size = size;
    table->count = 0;
    table->active = 0;
    // инициализация ячеек
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < table->size; i++) 
    {
        table->bins[i] = empty_bin;
    }
    // копируем старые ячейки в новую таблицу
    for (struct bin *bin = begin; bin != end; bin++) 
    {
        if (!bin->is_empty) 
            add_internal(table, bin->hash_key, bin->key, bin->val);
    }
}
```




Она получает (новый) размер и (возможно, пустую) последовательность пустых ячеек, а затем обновляет все данные учета и перемещает ячейки в новую таблицу. Функция использует вспомогательную функцию `add_internal()`, которую мы определим позже, когда будем определять весь функционал для добавления данных. А пока достаточно объявить ее прототип и знать, что эта функция вставляет в таблицу пару "ключ-значение", получая на вход через параметры саму хеш-таблицу, хеш-значение и скопированные данные ключа и данных.




Теперь определим функцию для создания новой таблицы:



```c

// минимальный размер таблицы
#define MIN_SIZE 8
// создание новой таблицы
struct hash_table* new_table(struct key_type const *key_type, struct value_type const *value_type)
{
    struct hash_table *table = malloc(sizeof *table);
    table->key_type = key_type;
    table->value_type = value_type;
    init_table(table, MIN_SIZE, NULL, NULL);
    return table;
}
```



При создании новой таблицы мы инициализируем ее начальным размером (в данном случае это константа `MIN_SIZE`) и пустой последовательностью существующих ячеек (аргументы begin и end равны NULL).



И определим функцию для изменения размера таблицы:



```c

void resize(struct hash_table* table, unsigned int new_size)
{
    // Сохраняем старые ячейки для последующего перемещения данных
    struct bin *old_bins_begin = table->bins,                   // указатель на начало ячеек
                *old_bins_end = old_bins_begin + table->size;   // указатель на конец ячеек
    // обновляем таблицу и копируем данные из старых активных ячеек в новые ячейки 
    init_table(table, new_size, old_bins_begin, old_bins_end);
    // освобождаем память под старые ячейки
    free(old_bins_begin);
}
```



Для изменения размера вызывается функция `init_table()` с новым размером и существующими ячейками. Поскольку `init_table` перезапишет указатель на ячейки в структуре таблицы, сохраняем указатель на старые ячейки в переменную old_bins_begin, чтобы потом освободить их. После изменения размера указатели на ключи и значения перемещаются в новые ячейки с помощью `init_table()` и `add_internal()`, поэтому при удалении старых ячеек не произойдет утечки памяти приложения.



### Удаление таблицы



При удалении таблицы нам нужно освобождать память как структуры хеш-таблицы и ее ячеек, так и данных, которые копируются в таблицу:



```c

// Удаление таблицы, ее ячеек и данных в ней
// очистка данных отдельной ячейки
void free_bin(struct hash_table* table, struct bin* bin)
{
    if (is_active_bin(bin)) 
    {
        free_key(table, bin->key);
        free_val(table, bin->val);
        bin->is_empty = 1;   // указываем, что данные корзины удалены
        table->active--;    // одной активной ячейкой меньше
    }
}
// удаление таблицы и ее ячеек
void delete_table(struct hash_table *table)
{
    for (struct bin *bin = table->bins; bin != table->bins + table->size; ++bin) 
    {
        free_bin(table, bin);
    }
    free(table->bins);
    free(table);
}
```



Процесс удаления довольно прост: мы проходим по каждой ячейке и освобождаем все ее данные. Мы можем определить, содержит ли ячейка данные, по установленным в ней флагам, и проверить это с помощью вспомогательной функции `is_active_bin()`. Если данные там есть, необходимо освободить ключ и значение, что делается с помощью вспомогательных функций `free_key()` и `free_val()`, которые обрабатывают типы ключа и значения соответственно.



Функция free_bin() игнорирует неактивные ячейки, поэтому ее можно безопасно вызывать с неактивными зондами. Если текущая ячейка принадлежит последовтельности зондирования и не является пустой (то есть активная ячейка), то эта функция освободит данные ячейки и обновит счетчик активных ячеек, который необходим для изменения размера.




### Поиск



Для проверка наличия ключа в ячейке сначала определим вспомогательную функцию:



```c

int key_in_bin(struct hash_table* table, struct bin* bin, unsigned int hash_key, void const* key)
{
    return is_active_bin(bin) && bin->hash_key == hash_key && table->key_type->cmp(bin->key, key);
}
```



Прежде всего для поиска ключей используем только активные ячейки, то есть не пустые ячейки в последовательности зондирования (в противном случае совпадение ключа будет ложным или соответствовать удаленному ключу). Кроме того, функция сравнения типа ключа (table->key_type->cmp) должна подтвердить равенство ключей.



Теоретически можно было бы проверить только эти два условия (активность ячейки и совпадание ключей без хеш-ключей), поскольку равенство ключей уже предполагает равенство хеш-ключей. Тем не менее, сравнивая сначала хеш-функции, можно избежать вызова функции сравнения в (весьма вероятных) случаях, когда разные ключи имеют разные хеш-значения.



Далее нам нужен код для поиска ячейки, которая содержит ключ. В этом случае мы можем просто пройти в цикле по ячейкам в последовательности зондирования пока не дойдем до ячейки с совпадающим ключом или до пустой ячейки. Чтобы данный код поиска использовать позже также при вставке и удалении, выделим его в отдельную функцию:



```c

struct bin* find_key(struct hash_table* table, unsigned int hash_key, void const *key)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        struct bin* bin = table->bins + p(hash_key, i, table->size);
        if (!bin->in_probe || key_in_bin(table, bin, hash_key, key)) return bin;
    }
}
```



И затем определим собственно функцию поиска, которая будет применять вышеопределенную функцию:



```c

void* const lookup_key(struct hash_table *table, void const *key)
{
    struct bin *bin = find_key(table, hash(table, key), key);
    return bin->in_probe ? bin->val : NULL;
}
```



Эта функция возвращает указатель на значение, хранящееся в таблице, поэтому это не копия. Следовательно, возвращаемое значение имеет тип `void* const`. Можно было бы также вернуть копию (и тогда пользователю всегда пришлось бы освобождать возвращаемое значение), но в большинстве случаев использования хеш-таблиц требуется указатель на значение без присвоения права собственности, поэтому функция реализована именно таким образом.




### Удаление элементов



При удалении используем вышеопределенную функцию find_key() для поиска ячейки с нужным хеш-ключом и затем удаляем ее (если она найдена):



```c

void delete_key(struct hash_table* table, void const *key)
{
    struct bin *bin = find_key(table, hash(table, key), key);
    free_bin(table, bin);
    // если количество активных ячеек меньше некоторого порога, сжимаем таблицу
    if (table->active < table->size / 8 && table->size > MIN_SIZE)
        resize(table, table->size / 2);
}
```



Причина, по которой можно вызвать `free_bin()` для результата `find_key()` без проверки, найдено ли что-либо, заключается в том, что `free_bin()` удаляет только значения в активном ячейке. Если мы не нашли ключ, `find_key()` вернул бы вам неактивную ячейку, и тогда `free_bin()` ничего бы не сделал. Таким образом, данные освобождаются только в том случае, если таблица содержит ключ.




### Поиск ячеек



Кроме поиска элементов в хеш-таблице нам также необходим функционал для поиска ячеек. Поэтому определим несколько функций, которые, используя функцию `find_key()`, возвращает ячейки:



```c

// находит первую пустую ячейку
struct bin* find_empty(struct hash_table *table, unsigned int hash_key)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        struct bin *bin = table->bins + p(hash_key, i, table->size);
        if (bin->is_empty) return bin;
    }
}

// поиска ячейки с определенным ключом
struct bin* get_bin(struct hash_table* table, unsigned int hash_key, void *const key)
{
    struct bin *bin = find_key(table, hash_key, key);
    return bin->in_probe ? bin : find_empty(table, hash_key);
}
```



Первая функция - `find_empty()` возвращает пустую ячейку. Вторая функция - `get_bin()` призвана найти ячейку с определенным ключом. Однако если нужного ключа не оказалось, то функция возвращает перву, попавшуюся свободную ячейку.




### Добавление элементов



Функционал добавления будет состоять из трех функций. Первая функция будет отвечать за сохранение пары ключ/значение в ячейке:



```c

void store_in_bin(struct hash_table* table, struct bin *bin, unsigned int hash_key, void *key, void *value)
{
    // обновляем счетчики на основе текущего состояния ячейки
    table->active += bin->is_empty;
    table->count += !bin->in_probe;
    // освобождаем память ключа и значения, которые находятся в ячейке
    free_bin(table, bin);
    // сохраняем в ячейку новый ключ и значение
    *bin = (struct bin) { .in_probe = 1, .is_empty = 0, .hash_key = hash_key, .key = key, .val = value };
}
```



Первые две строки обновляют поля-счетчики таблицы. С помощью этих счетчиков мы отслеживаем, сколько ячеек используется (то есть входят в последовательность зондирования - `count`) и сколько являются активными (то есть являются частью зонда и не пусты - `active`). Флаги `in_probe` и `is_empty` в ячейке содержат всю необходимую информацию для обновления счетчиков. Добавление `is_empty` к `active` позволит увеличивать `active` только в том случае, если ячейка ранее была пуста (`is_empty=1`). Аналогично добавление `!in_probe` к `count` увеличит `count` только тогда, когда ячейка не находится в зонде.



После обновления счетчиков мы освобождаем все значения, уже находящиеся в ячейке, а затем обновляем ячейку новыми значениями.



Далее определим вспомогательную функцию для добавления - `add_internal()`:

 

```c

void add_internal(struct hash_table* table, unsigned int hash_key, void* key_copy, void* value_copy)
{
    struct bin *bin = get_bin(table, hash_key, key_copy);
    store_in_bin(table, bin, hash_key, key_copy, value_copy);
    if (table->count > table->size / 2) resize(table, table->size * 2);
}
```



Здесь с помощью `get_bin()` получаем ячейку для вставки данных. Далее применяем выше определенную функцию `store_in_bin()` для сохранения данных в полученной ячейке и затем при необходимости расширяем хеш-таблицу.



Но эта вспомогательная функция, основная же функция для добавления будет использовать выше определенную:



```c

void add(struct hash_table* table, void const *key, void const *value)
{
    unsigned int hash_key = hash(table, key);
    void *key_copy = copy_key(table, key);
    void *value_copy = copy_val(table, value);
    add_internal(table, hash_key, key_copy, value_copy);
}
```



Вызываемая пользователем функция `add()` должна вычислить ключ хеша из пользовательского ключа и скопировать ключ и значение и для собственно добавления передает данные во вспомогательную функцию `add_internal`.



### Полный пример применения



Рассмотрим на примере, как мы можем применить весь выше описанный функционал хеш-таблицы. В качестве используемого типа данных возьмем строки, причем и ключи, и значения будут строками:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// тип для функции хеширования
typedef unsigned int (*hash_func)(void const *);
// тип для функции сравнения
typedef int (*compare_func)(void const *, void const *);
// тип для функции освобождения памяти
typedef void (*destructor_func)(void *);
// тип для функции копирования данных
typedef void *(*copy_func)(void const *);

// тип ключей
struct key_type 
{
    hash_func hash;
    compare_func cmp;
    copy_func cpy;
    destructor_func del;
};
// тип значений
struct value_type 
{
    copy_func cpy;
    destructor_func del;
};

// структура ячейки хеш-таблицы
struct bin 
{
    int in_probe : 1;       // является ли ячейка частью последовательности зондирования
    int is_empty : 1;       // является ли ячейка пустой
    unsigned int hash_key; // хеш-ключ
    void *key;              // указатель на ключ
    void *val;              // указатель на значение
};
// структура хеш-таблицы
struct hash_table 
{
    struct bin *bins;
    unsigned int size;
    unsigned int count;
    unsigned int active;
    struct key_type const *key_type;
    struct value_type const *value_type;
};

// линейное зондирование
unsigned int p(unsigned int key, unsigned int i, unsigned int m)
{
    return (key + i) & (m - 1);
}

// хеш-функция типа ключа для сопоставления пользовательского ключа с хеш-ключом
unsigned int hash(struct hash_table *table, void const *key)
{
    return table->key_type->hash(key);
}

// копирование ключей
void* copy_key(struct hash_table *table, void const *key)
{
    return table->key_type->cpy(key);
}
// копирование значений
void* copy_val(struct hash_table *table, void const *val)
{
    return table->value_type->cpy(val);
}
// освобождение памяти ключей
void free_key(struct hash_table *table, void *key)
{
    table->key_type->del(key);
}
// освобождение памяти значений
void free_val(struct hash_table *table, void *val)
{
    table->value_type->del(val);
}
// проверяем, является ли ячейка таблицы активной - является ли она частью последовательности зондирования и не является пустой
int is_active_bin(struct bin *bin)
{
    return bin->in_probe && !bin->is_empty;
}

// вспомогательная функция для добавления данных
// на вход получает хеш-ключ и копирует ключ и значение, вставляя данные в таблицу
void add_internal(struct hash_table *table, unsigned int hash_key, void *key_copy, void *value_copy);
// Инициализирует таблицу и затем копирует ячейки из begin в end
void init_table(struct hash_table *table, unsigned int size, struct bin *begin, struct bin *end)
{
    // инициализация полей структуры
    table->bins = malloc(size * sizeof *table->bins);
    table->size = size;
    table->count = 0;
    table->active = 0;
    // инициализация ячеек
    struct bin empty_bin = {.in_probe = 0, .is_empty = 1};
    for (unsigned int i = 0; i < table->size; i++) 
    {
        table->bins[i] = empty_bin;
    }
    // копируем старые ячейки в новую таблицу
    for (struct bin *bin = begin; bin != end; bin++) 
    {
        if (!bin->is_empty) 
            add_internal(table, bin->hash_key, bin->key, bin->val);
    }
}

// минимальный размер таблицы
#define MIN_SIZE 8
// создание новой таблицы
struct hash_table* new_table(struct key_type const *key_type, struct value_type const *value_type)
{
    struct hash_table *table = malloc(sizeof *table);
    table->key_type = key_type;
    table->value_type = value_type;
    init_table(table, MIN_SIZE, NULL, NULL);
    return table;
}

// изменение размера таблицы
void resize(struct hash_table* table, unsigned int new_size)
{
    // Сохраняем старые ячейки для последующего перемещения данных
    struct bin *old_bins_begin = table->bins,                   // указатель на начало ячеек
                *old_bins_end = old_bins_begin + table->size;   // указатель на конец ячеек
    // обновляем таблицу и копируем данные из старых активных ячеек в новые ячейки 
    init_table(table, new_size, old_bins_begin, old_bins_end);
    // освобождаем память под старые ячейки
    free(old_bins_begin);
}

// Удаление таблицы, ее ячеек и данных в ней
// очистка данных отдельной ячейки
void free_bin(struct hash_table* table, struct bin* bin)
{
    if (is_active_bin(bin)) 
    {
        free_key(table, bin->key);
        free_val(table, bin->val);
        bin->is_empty = 1;   // указываем, что данные корзины удалены
        table->active--;    // одной активной ячейкой меньше
    }
}
// удаление таблицы и ее ячеек
void delete_table(struct hash_table *table)
{
    for (struct bin *bin = table->bins; bin != table->bins + table->size; ++bin) 
    {
        free_bin(table, bin);
    }
    free(table->bins);
    free(table);
}


// поиск данных
// проверяем, что ячейка содержит ключ
// сначала мы проверяем, является ли ячейка активной 
// затем, если хеш-ключи совпадают, сравниваем ключи
int key_in_bin(struct hash_table* table, struct bin* bin, unsigned int hash_key, void const* key)
{
    return is_active_bin(bin) && bin->hash_key == hash_key && table->key_type->cmp(bin->key, key);
}

// поиск, пока не дойдем до ячейки с нужным ключом или до пустой ячейки 
// ячейка должна быть не пустой и быть частью последовательности зондирования
struct bin* find_key(struct hash_table* table, unsigned int hash_key, void const *key)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        struct bin* bin = table->bins + p(hash_key, i, table->size);
        if (!bin->in_probe || key_in_bin(table, bin, hash_key, key)) return bin;
    }
}
void *const lookup_key(struct hash_table *table, void const *key)
{
    struct bin *bin = find_key(table, hash(table, key), key);
    return bin->in_probe ? bin->val : NULL;
}


// находит первую пустую ячейку
struct bin* find_empty(struct hash_table *table, unsigned int hash_key)
{
    for (unsigned int i = 0; i < table->size; i++) 
    {
        struct bin *bin = table->bins + p(hash_key, i, table->size);
        if (bin->is_empty) return bin;
    }
}

// поиска ячейки с определенным ключом
struct bin* get_bin(struct hash_table* table, unsigned int hash_key, void *const key)
{
    struct bin *bin = find_key(table, hash_key, key);
    return bin->in_probe ? bin : find_empty(table, hash_key);
}

// удаление данных
void delete_key(struct hash_table* table, void const *key)
{
    struct bin *bin = find_key(table, hash(table, key), key);
    free_bin(table, bin);
    // если количество активных ячеек меньше некоторого порога, сжимаем таблицу
    if (table->active < table->size / 8 && table->size > MIN_SIZE)
        resize(table, table->size / 2);
}

// ДОБАВЛЕНИЕ 
// сохранение данных в ячейке хеш-таблицы
void store_in_bin(struct hash_table* table, struct bin *bin, unsigned int hash_key, void *key, void *value)
{
    // обновляем счетчики на основе текущего состояния ячейки
    table->active += !!bin->is_empty;
    table->count += !bin->in_probe;
    // освобождаем память ключа и значения, которые находятся в ячейке
    free_bin(table, bin);
    // сохраняем в ячейку новый ключ и значение
    *bin = (struct bin) { .in_probe = 1, .is_empty = 0, .hash_key = hash_key, .key = key, .val = value };
}
// вспомогательная функция для добавления
void add_internal(struct hash_table* table, unsigned int hash_key, void* key_copy, void* value_copy)
{
    struct bin *bin = get_bin(table, hash_key, key_copy);
    store_in_bin(table, bin, hash_key, key_copy, value_copy);
    if (table->count > table->size / 2) resize(table, table->size * 2);
}
// основная функция добавления
void add(struct hash_table* table, void const *key, void const *value)
{
    unsigned int hash_key = hash(table, key);
    void *key_copy = copy_key(table, key);
    void *value_copy = copy_val(table, value);
    add_internal(table, hash_key, key_copy, value_copy);
}

// функция хеширования - получаем хеш-значение из строки алгоритмом FNV-1a
unsigned int hash_fnv1a(const char *str) 
{
   unsigned int hash = 2166136261u;

    while (*str) {
        hash ^= (unsigned char)(*str++);
        hash *= 16777619;
    }

    return hash;
}

unsigned int str_hash(void const* key)
{
    return hash_fnv1a((char const*) key);
}

// функция сравнения строк
int str_cmp(void const *s_1, void const *s_2)
{
    char* str_1 = (char*)s_1;
    char* str_2 = (char*)s_2;
    return strcmp(str_1, str_2) == 0;
}

// функция копирования строк
void* str_copy(const void *p)
{
    const char* str = p;
    return strdup(str);
}
// вывод хеш-таблицы
void print_table(struct hash_table* table)
{
    for (int i =0; i < table->size; ++i) 
    {
        struct bin* bin = table->bins + i;
        printf("bin %d: ", i);
        if(!bin->is_empty && bin->in_probe) 
        {
            printf("%s: %s\n", (char*) bin->key, (char*) bin->val);
        }
        else
        {
            printf("---\n");
        }
    }
}

// структура ключей для работы со строками
struct key_type str_key_type = {.cmp = str_cmp, .del = free, .hash = str_hash, .cpy = str_copy};
// структура значений для работы со строками
struct value_type str_val_type = {.del = free, .cpy = str_copy};

int main(void)
{
    // ключи
    char* keys[] = {"red", "blue", "green", "yellow", "white"};
    // значения
    char* values[] = {"rouge", "bleu", "vert", "jaune", "blanc"};

    // создаем таблицу
    struct hash_table *map = new_table(&str_key_type, &str_val_type);

    // добавляем данные
    for (int i = 0; i < sizeof(keys)/sizeof(keys[0]); ++i) 
    {
        add(map, keys[i], values[i]);
    }
    // выводим на консоль
    print_table(map);

    putchar(10);  // для разделения консольного вывода

    // проверяем наличие ключа "red"
    char* red= "red";
    void *val = lookup_key(map, red);
    if(val) printf("`red` is present\n");
    else  printf("`red` is absent\n");

    // удаляем элемент с ключом "red"
    delete_key(map, red);
  
    // повторно проверяем наличие ключа "red"
    val = lookup_key(map, red);
    if(val) printf("`red` is present\n");
    else  printf("`red` is absent\n");

    putchar(10);  // для разделения консольного вывода

    // повторно выводим на консоль
    print_table(map);

    // удаляем хеш-таблицу
    delete_table(map);
    return 0;
}
```



В данном случае в качестве типа данных для ключей и значений мы используем строки или точнее тип `char*`. И для этого определяем две соответствующие структуры:



```c

// структура ключей для работы со строками
struct key_type str_key_type = {.cmp = str_cmp, .del = free, .hash = str_hash, .cpy = str_copy};
// структура значений для работы со строками
struct value_type str_val_type = {.del = free, .cpy = str_copy};
```



Обе структуры устанавливают ряд функций для работы с ключами и значениями. В качестве функции для освобождения памяти (поле `del`) применяется встроенная библиотечная функция `free()`. Для остальных операций определяем специальные функции:



```c

unsigned int str_hash(void const* key)
{
    return hash_fnv1a((char const*) key);
}

// функция сравнения строк
int str_cmp(void const *s_1, void const *s_2)
{
    char* str_1 = (char*)s_1;
    char* str_2 = (char*)s_2;
    return strcmp(str_1, str_2) == 0;
}

// функция копирования строк
void* str_copy(const void *p)
{
    const char* str = p;
    return strdup(str);
}
```



Поскольку у нас типы-указатели на функции в качестве параметра принимают значение типа `const void *`, то и данные функции принимают параметр этого типа. Но так как за этими указателями будут скрываться строки, то внутри функции преобразуем эти значения в указатели типа `char*` и для получения финального результата применяем другие функции для работы со строками. Так, для хеширования используем функцию `hash_fnv1a`, которая реализует алгоритм FNV-1a. При сравнении используем библиотечную функцию `strcmp()`, а при копировании строк - другую библиотечную функцию `strdup()`



Для просмотра содержимого хеш-таблицы определяем вспомогательную функцию print_table. В основной части программы - в функции main определяем два массива строк одинаковой длины - keys и values (условно говоря, названия цветов на английском и французском языках) и добавляем их в хеш-таблицу. Затем с помощью print_table смотрим содержимое таблицы, пробуем удалить определенный ключ и проверяем его наличие до и после удаления. Консольный вывод программы:



